    read.mock.calls.filter((call) => call[1] === '.change-owner-partitions.json'),
  ).toHaveLength(1);
  expect(read.mock.calls.filter((call) => [activeRef, historyRef].includes(call[1]))).toHaveLength(
    0,
  );
  expect(write).not.toHaveBeenCalled();
})

